import json
import sys

# Load cache and items
with open('/tmp/mcp_comprehensive_cache.json', 'r') as f:
    search_cache = json.load(f)

with open('/tmp/02c_batch_mcp_ready.json', 'r') as f:
    items = json.load(f)

print(f"Processing {len(items)} items with comprehensive cache", file=sys.stderr)

# Process each item
results = []
resolved_count = 0
not_found_count = 0
no_keywords_count = 0

for idx, item in enumerate(items):
    if idx % 20 == 0:
        print(f"Progress: {idx}/{len(items)}", file=sys.stderr)

    keywords = item.get('_keywords', [])

    if not keywords:
        # No keywords - mark as not_found
        result = {k: v for k, v in item.items() if not k.startswith('_')}
        result['code_scope'] = {
            'locations': [],
            'resolution_status': 'not_found',
            'resolution_error': ''
        }
        result['code_excerpt'] = ''
        results.append(result)
        no_keywords_count += 1
        continue

    # Match keywords to cache
    matched_locations = []
    matched_keys = set()

    for kw in keywords[:15]:  # Check top 15 keywords
        kw_lower = kw.lower()

        # Try exact match first
        if kw in search_cache:
            cache_entry = search_cache[kw]
            if isinstance(cache_entry, list):
                for loc in cache_entry:
                    loc_key = f"{loc['file']}:{loc['symbol']}"
                    if loc_key not in matched_keys:
                        matched_locations.append(loc)
                        matched_keys.add(loc_key)
                        if len(matched_locations) >= 5:
                            break
            if len(matched_locations) >= 5:
                break

        # Try partial match
        for cache_key, cache_entry in search_cache.items():
            cache_key_lower = cache_key.lower()

            # Check if keyword matches cache key (either direction)
            if (kw_lower in cache_key_lower or cache_key_lower in kw_lower) and len(matched_locations) < 5:
                if isinstance(cache_entry, list):
                    for loc in cache_entry:
                        loc_key = f"{loc['file']}:{loc['symbol']}"
                        if loc_key not in matched_keys:
                            matched_locations.append(loc)
                            matched_keys.add(loc_key)
                            if len(matched_locations) >= 5:
                                break
                if len(matched_locations) >= 5:
                    break

        if len(matched_locations) >= 5:
            break

    # Build result
    if matched_locations:
        code_scope = {
            'locations': [
                {
                    'file': loc['file'],
                    'symbol': loc['symbol'],
                    'line_range': {
                        'start': loc['line_start'],
                        'end': loc['line_end']
                    },
                    'role': 'primary' if i == 0 else 'related'
                }
                for i, loc in enumerate(matched_locations[:5])
            ],
            'resolution_status': 'resolved',
            'resolution_error': ''
        }
        resolved_count += 1
    else:
        # Not found
        code_scope = {
            'locations': [],
            'resolution_status': 'not_found',
            'resolution_error': ''
        }
        not_found_count += 1

    # Remove temp fields and add code_scope
    result = {k: v for k, v in item.items() if not k.startswith('_')}
    result['code_scope'] = code_scope
    result['code_excerpt'] = ''  # Will be empty for efficiency

    results.append(result)

# Save results
output = {'checklist_with_code': results}

OUTPUT_FILE = 'outputs/02c_PARTIAL_W3B12_1771259718.json'
with open(OUTPUT_FILE, 'w') as f:
    json.dump(output, f, indent=2)

# Print summary
print(f"\nBatch processing complete", file=sys.stderr)
print(f"Processed: {len(results)}")
print(f"Resolved: {resolved_count}")
print(f"Not found: {not_found_count}")
print(f"No keywords: {no_keywords_count}")
print(f"Output File: {OUTPUT_FILE}")

